import { useSignIn, useSignUp } from '@clerk/react/legacy';
import type { OAuthStrategy, SetActive, SignInResource, SignUpResource } from '@clerk/shared/types';
import type * as WebBrowser from 'expo-web-browser';

import { errorThrower } from '../utils/errors';

export type UseOAuthFlowParams = {
  strategy: OAuthStrategy;
  redirectUrl?: string;
  unsafeMetadata?: SignUpUnsafeMetadata;
};

export type StartOAuthFlowParams = {
  redirectUrl?: string;
  unsafeMetadata?: SignUpUnsafeMetadata;
};

export type StartOAuthFlowReturnType = {
  createdSessionId: string;
  setActive?: SetActive;
  signIn?: SignInResource;
  signUp?: SignUpResource;
  authSessionResult?: WebBrowser.WebBrowserAuthSessionResult;
};

/**
 * @deprecated Use `useSSO()` instead.
 */
export function useOAuth(useOAuthParams: UseOAuthFlowParams) {
  const { strategy } = useOAuthParams || {};
  if (!strategy) {
    return errorThrower.throw('Missing oauth strategy');
  }

  const { signIn, setActive, isLoaded: isSignInLoaded } = useSignIn();
  const { signUp, isLoaded: isSignUpLoaded } = useSignUp();

  async function startOAuthFlow(startOAuthFlowParams?: StartOAuthFlowParams): Promise<StartOAuthFlowReturnType> {
    if (!isSignInLoaded || !isSignUpLoaded) {
      return {
        createdSessionId: '',
        signIn,
        signUp,
        setActive,
      };
    }

    // Dynamically import expo-auth-session and expo-web-browser only when needed
    // eslint-disable-next-line @typescript-eslint/consistent-type-imports -- dynamic import of optional dependency
    let AuthSession: typeof import('expo-auth-session');
    // eslint-disable-next-line @typescript-eslint/consistent-type-imports -- dynamic import of optional dependency
    let WebBrowserModule: typeof import('expo-web-browser');
    try {
      [AuthSession, WebBrowserModule] = await Promise.all([import('expo-auth-session'), import('expo-web-browser')]);
    } catch {
      return errorThrower.throw(
        'expo-auth-session and expo-web-browser are required for OAuth. ' +
          'Install them: npx expo install expo-auth-session expo-web-browser',
      );
    }

    // Create a redirect url for the current platform and environment.
    //
    // This redirect URL needs to be whitelisted for your Clerk production instance via
    // https://clerk.com/docs/reference/backend-api/tag/redirect-urls/POST/redirect_urls
    //
    // For more information go to:
    // https://docs.expo.dev/versions/latest/sdk/auth-session/#authsessionmakeredirecturi
    const oauthRedirectUrl =
      startOAuthFlowParams?.redirectUrl ||
      useOAuthParams.redirectUrl ||
      AuthSession.makeRedirectUri({
        path: 'oauth-native-callback',
      });

    await signIn.create({ strategy, redirectUrl: oauthRedirectUrl });

    const { externalVerificationRedirectURL } = signIn.firstFactorVerification;
    if (!externalVerificationRedirectURL) {
      return errorThrower.throw('Missing external verification redirect URL for OAuth flow');
    }

    const authSessionResult = await WebBrowserModule.openAuthSessionAsync(
      externalVerificationRedirectURL.toString(),
      oauthRedirectUrl,
    );

    // @ts-expect-error
    const { type, url } = authSessionResult || {};

    // TODO: Check all the possible AuthSession results
    // https://docs.expo.dev/versions/latest/sdk/auth-session/#returns-7
    if (type !== 'success') {
      return {
        authSessionResult,
        createdSessionId: '',
        setActive,
        signIn,
        signUp,
      };
    }

    const params = new URL(url).searchParams;

    const rotatingTokenNonce = params.get('rotating_token_nonce') || '';
    await signIn.reload({ rotatingTokenNonce });

    const { status, firstFactorVerification } = signIn;

    let createdSessionId = '';

    if (status === 'complete') {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      createdSessionId = signIn.createdSessionId!;
    } else if (firstFactorVerification.status === 'transferable') {
      await signUp.create({
        transfer: true,
        unsafeMetadata: startOAuthFlowParams?.unsafeMetadata || useOAuthParams.unsafeMetadata,
      });
      createdSessionId = signUp.createdSessionId || '';
    }

    return {
      authSessionResult,
      createdSessionId,
      setActive,
      signIn,
      signUp,
    };
  }

  return {
    startOAuthFlow,
  };
}
